511:where
512:    S: StreamingSource<T>,
513:{
514:    /// Fetch the next message from this stream.
515:    ///
516:    /// # Return value
517:    ///
518:    /// - `Result::Err(val)` means a gRPC error was sent by the sender instead
519:    ///   of a valid response message. Refer to [`Status::code`] and
520:    ///   [`Status::message`] to examine possible error causes.
521:    ///
522:    /// - `Result::Ok(None)` means the stream was closed by the sender and no
523:    ///   more messages will be delivered. Further attempts to call
524:    ///   [`Streaming::message`] will result in the same return value.
525:    ///
526:    /// - `Result::Ok(Some(val))` means the sender streamed a valid response
527:    ///   message `val`.
528:    ///
529:    /// ```rust
530:    /// # use tonic::{Streaming, Status, codec::Decoder};
531:    /// # use std::fmt::Debug;
532:    /// # async fn next_message_ex<T, D>(mut request: Streaming<T>) -> Result<(), Status>
533:    /// # where T: Debug + 'static,
534:    /// # D: Decoder<Item = T, Error = Status> + Send  + 'static,
535:    /// # {
536:    /// if let Some(next_message) = request.message().await? {
537:    ///     println!("{:?}", next_message);
538:    /// }
539:    /// # Ok(())
540:    /// # }
541:    /// ```
542:    pub async fn message(&mut self) -> Result<Option<T>, Status> {
543:        match future::poll_fn(|cx| {
544:            // SAFETY: `message` borrows `self` mutably for the entire returned
545:            // future, so callers cannot move the stream while this poll is in
546:            // progress.
547:            unsafe { Pin::new_unchecked(&mut *self) }.poll_next(cx)
548:        })
549:        .await
550:        {
551:            Some(Ok(m)) => Ok(Some(m)),
552:            Some(Err(e)) => Err(e),
553:            None => Ok(None),
554:        }
555:    }
556:
557:    /// Fetch the trailing metadata.
558:    ///
559:    /// This will drain the stream of all its messages to receive the trailing
560:    /// metadata. If [`Streaming::message`] returns `None` then this function
561:    /// will not need to poll for trailers since the body was totally consumed.
562:    ///
563:    /// ```rust
564:    /// # use tonic::{Streaming, Status};
565:    /// # async fn trailers_ex<T: 'static>(mut request: Streaming<T>) -> Result<(), Status> {
566:    /// if let Some(metadata) = request.trailers().await? {
567:    ///     println!("{:?}", metadata);
568:    /// }
569:    /// # Ok(())
570:    /// # }
571:    /// ```
572:    pub async fn trailers(&mut self) -> Result<Option<MetadataMap>, Status> {
573:        // Shortcut to see if we already pulled the trailers in the stream step
574:        // we need to do that so that the stream can error on trailing grpc-status
575:        if let Some(trailers) = self.trailers.take() {
576:            return Ok(Some(MetadataMap::from_headers(trailers)));
577:        }
578:
579:        // To fetch the trailers we must clear the body and drop it.
580:        while self.message().await?.is_some() {}
581:
582:        // Since we call poll_trailers internally on poll_next we need to
583:        // check if it got cached again.
584:        if let Some(trailers) = self.trailers.take() {
585:            return Ok(Some(MetadataMap::from_headers(trailers)));
586:        }
587:
588:        // We've polled through all the frames, and still no trailers, return None
589:        Ok(None)
590:    }
591:}
