598:
599:    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
600:        let mut this = self.project();
601:
602:        loop {
603:            match ready!(this.inner.as_mut().get_pin_mut().poll_next(cx)) {
604:                Some(Ok(StreamingEvent::Message(item))) => return Poll::Ready(Some(Ok(item))),
605:                Some(Ok(StreamingEvent::Trailers(trailers))) => *this.trailers = Some(trailers),
606:                Some(Err(status)) => return Poll::Ready(Some(Err(status))),
607:                None => return Poll::Ready(None),
608:            }
609:        }
610:    }
